export const tableKeymap = keymap.of([
  {
    key: 'Tab',
    run: (view) => {
      if (isInTable(view)) {
        moveToNextCell(view);
        return true; // intercepta o Tab
      }
      return false;
    }
  },
  {
    key: 'Shift-Tab',
    run: (view) => {
      if (isInTable(view)) {
        moveToPrevCell(view);
        return true;
      }
      return false;
    }
  },
  {
    key: 'Enter',
    run: (view) => {
      if (isInTable(view)) {
        moveToNextRow(view);
        return true;
      }
      return false;
    }
  }
]);
